from pathlib import Path
import json
r=Path((Path(__file__).resolve().parents[1]/'outputs/annotation-smoke/latest-trial.txt').read_text().strip())
data=json.loads((r/'labels.json').read_text())
report=json.loads((r/'validation.json').read_text()) if (r/'validation.json').exists() else {}
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>新版七动作 · 视频审核</title>
<style>*{box-sizing:border-box}body{margin:0;background:#10151c;color:#e7edf5;font:16px/1.5 system-ui,sans-serif}header{padding:20px 28px;border-bottom:1px solid #303947}h1{font-size:22px;margin:0}p{color:#a9b8c9;margin:6px 0}main{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(320px,1fr);gap:22px;padding:24px}video{width:100%;background:#000;max-height:65vh}.left{position:sticky;top:16px;align-self:start}button,select{font:inherit;border:1px solid #40536b;border-radius:7px;background:#1d2a3a;color:#e7edf5;padding:8px 12px;cursor:pointer}.controls{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.current{padding:18px;background:#1c2c3d;border-radius:8px;min-height:110px}.step{display:block;width:100%;text-align:left;margin-bottom:8px;background:#151e29}.step small{display:block;color:#a9b8c9}.step.active{border-color:#6ab9ff;background:#213e59}.caption{font-size:19px;margin-top:8px}.status{color:#7fc4ff}a{color:#8ecbff} @media(max-width:850px){main{grid-template-columns:1fr}.left{position:static}video{max-height:50vh}}</style>
<header><p style="color:#ffbf69">本次结果未通过新版校验，不是合格标注。详情见视频下方检查结果。</p><h1>新版七动作 · 视频审核</h1><p>Wuji · episode 000000 · cam0 · 177.67 秒 · __COUNT__ 段模型标注，格式校验失败 · 原始返回仅供人工查看</p></header>
<main><section class="left"><video id="video" controls preload="metadata" src="episode_000000_cam0.mp4"></video><div class="controls"><button id="prev">上一段</button><button id="replay">重播当前段</button><button id="next">下一段</button><label>速度 <select id="speed"><option value="0.5">0.5×</option><option value="1" selected>1×</option><option value="1.5">1.5×</option><option value="2">2×</option></select></label><label><input type="checkbox" id="loop">循环当前段</label></div><div class="current"><div class="status" id="time"></div><div class="caption" id="caption"></div></div><p>点击右侧标注跳转播放。标签保留模型原文，便于核对双手分工和时间边界。</p><p>仅本地查看，不调用模型、不修改源数据、不上传审核结果。</p><p><a href="labels.json" download>下载原始标注 JSON</a></p><p id="error" role="alert"></p><details open><summary>新版自动检查结果</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere" id="checks"></pre></details></section><section id="steps" aria-label="动作标注列表"></section></main>
<script>
const report=__REPORT__; document.getElementById('checks').textContent=JSON.stringify(report,null,2); const data=__DATA__, steps=data.steps, video=document.getElementById('video'), list=document.getElementById('steps');let active=0,selected=0;
function fmt(t){return Math.floor(t/60)+':'+(t%60).toFixed(2).padStart(5,'0')}
const buttons=steps.map((s,i)=>{const b=document.createElement('button');b.className='step';const head=document.createElement('small');head.textContent=`${String(i+1).padStart(2,'0')} · ${fmt(s.start_sec)} — ${fmt(s.end_sec)}`;const text=document.createElement('div');text.textContent=s.text; const details=document.createElement('small');details.textContent=[s.phase,s.target_id?'目标 '+s.target_id:'',s.attempt_id?'尝试 '+s.attempt_id:'',s.outcome?'结果 '+s.outcome:'',s.evidence_note||''].filter(Boolean).join(' · ');text.append(details);b.append(head,text);b.onclick=()=>jump(i);list.append(b);return b});
function render(){const t=video.currentTime;let index=steps.findIndex(s=>t>=s.start_sec&&t<s.end_sec);if(index<0&&t>=steps[steps.length-1].end_sec)index=steps.length-1;active=index;buttons.forEach((b,i)=>{b.classList.toggle('active',i===active);b.setAttribute('aria-current',i===active?'true':'false')});if(active<0){document.getElementById('time').textContent=fmt(t)+' / '+fmt(data.duration_s);document.getElementById('caption').textContent='此时间段模型未提供标注（时间轴存在缺口）';return}const s=steps[active];document.getElementById('time').textContent=`${fmt(t)} / ${fmt(data.duration_s)} · 第 ${active+1} / ${steps.length} 段 · ${fmt(s.start_sec)} — ${fmt(s.end_sec)}`;document.getElementById('caption').textContent=s.text}
function jump(i){selected=Math.max(0,Math.min(steps.length-1,i));video.currentTime=steps[selected].start_sec;render();video.play().catch(()=>{})}
video.addEventListener('timeupdate',()=>{if(document.getElementById('loop').checked&&video.currentTime>=steps[selected].end_sec){video.currentTime=steps[selected].start_sec}render()});video.addEventListener('seeked',render);video.addEventListener('loadedmetadata',render);video.addEventListener('error',()=>document.getElementById('error').textContent='视频加载失败，请确认视频与审核页面在同一目录。');document.getElementById('prev').onclick=()=>jump(active-1);document.getElementById('next').onclick=()=>jump(active+1);document.getElementById('replay').onclick=()=>jump(active);document.getElementById('speed').onchange=e=>video.playbackRate=Number(e.target.value);document.getElementById('loop').onchange=()=>selected=Math.max(0,active);render();
</script></html>'''
html=html.replace('__COUNT__',str(len(data['steps']))).replace('__REPORT__',json.dumps(report,ensure_ascii=False).replace('<','\\u003c'))
(r/'review.html').write_text(html.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('<','\\u003c')))
print(r/'review.html')
